pub fn run<'a>(
    config: &'a aws_config::SdkConfig,
    operation: &'a str,
    input: &'a Value,
    options: &'a Options,
) -> core::CommandFuture<'a> {
    Box::pin(async move {
        let mut config = aws_sdk_transcribestreaming::config::Builder::from(config);
        if let Some(endpoint) = &options.endpoint_url {
            config = config.endpoint_url(endpoint);
        }
        let client = aws_sdk_transcribestreaming::Client::from_conf(config.build());
        let output = Output::new(options.clone());
        let command: core::CommandFuture<'_> = match operation {
            "get_medical_scribe_stream" => {
                Box::pin(call_get_medical_scribe_stream(&client, input, &output))
            }
            "start_call_analytics_stream_transcription" => Box::pin(
                call_start_call_analytics_stream_transcription(&client, input, &output),
            ),
            "start_medical_scribe_stream" => {
                Box::pin(call_start_medical_scribe_stream(&client, input, &output))
            }
            "start_medical_stream_transcription" => Box::pin(
                call_start_medical_stream_transcription(&client, input, &output),
            ),
            "start_stream_transcription" => {
                Box::pin(call_start_stream_transcription(&client, input, &output))
            }
            _ => return Err(CliError::input(format!("unknown operation: {operation}"))),
        };
        command
            .await
            .map_err(|error| error.context("transcribe-streaming", operation))
    })
}
